<main class="container py-5"><h1 class="h2">Validar cupón en el comercio</h1><p class="text-muted">Solo pueden canjearse cupones vigentes, no usados y pertenecientes a la empresa seleccionada (o a tu propia empresa).</p>
<form class="card p-4 mb-4" method="post" action="<?=url('/empresa/canjes')?>"><?=Csrf::field()?>
<?php if(Auth::isAdmin()):?><div class="mb-3"><label class="form-label">Empresa propietaria del cupón</label><select name="id_empresa" class="form-select" required><option value="">Selecciona empresa</option><?php foreach($empresas as $em):?><option value="<?= (int)$em['id'] ?>"><?=e($em['nombre_comercial'])?></option><?php endforeach;?></select></div><?php endif;?>
<label for="codigo" class="form-label">Código único presentado por el cliente</label><div class="row g-2"><div class="col-md-8"><input id="codigo" name="codigo_cupon" class="form-control" maxlength="19" placeholder="SV-XXXXXXXXXXXXXXXX" required pattern="SV-[A-Fa-f0-9]{16}"></div><div class="col-md-4"><button class="btn btn-success w-100">Confirmar canje</button></div></div></form>
<div class="card p-3 table-responsive"><h2 class="h5">Últimos cupones de mi empresa</h2><table class="table table-striped align-middle"><thead><tr><th>Código</th><th>Oferta</th><th>Compra</th><th>Canje hasta</th><th>Estado</th><th>Canje realizado</th></tr></thead><tbody>
<?php foreach($cupones as $c):?><tr><td><code><?=e($c['codigo_cupon'])?></code></td><td><?=e($c['titulo'])?></td><td><?=e($c['fecha_compra'])?></td><td><?=e($c['fecha_limite_canje'])?></td><td><?=e($c['estado']==='disponible' && $c['fecha_limite_canje']<date('Y-m-d')?'vencido':$c['estado'])?></td><td><?=e($c['fecha_canje']??'—')?></td></tr><?php endforeach;?>
<?php if(!$cupones):?><tr><td colspan="6">Aún no hay cupones vendidos.</td></tr><?php endif;?></tbody></table></div></main><?php require __DIR__.'/../layouts/footer.php';?>
